/**
 * Карточка товара: описание, похожие чаи, ссылки на статьи.
 *
 * Три блока объединены в один сниппет намеренно. Раньше это были три отдельных,
 * и порядок вывода получался непредсказуемым: приоритеты хука у разных сниппетов
 * складывались не так, как ожидалось, и описание оказывалось последним.
 * В одном обработчике порядок задаётся явно.
 *
 * Шаблон карточки собран Elementor: woocommerce_after_single_product_summary
 * на ней не вызывается, а описание из post_content не выводится вообще —
 * тексты были написаны у всех товаров, но их не видели ни покупатели, ни поисковики.
 * Рабочая точка — woocommerce_after_single_product.
 */
add_action('woocommerce_after_single_product', function () {
    if (!function_exists('is_product') || !is_product()) return;

    waystea_card_description();
    waystea_card_terms();
    waystea_card_similar();
    waystea_card_articles();
}, 5);

/**
 * Пояснение терминов из названия товара.
 *
 * «Цзинь Хао», «Мао Фэн» и «N категория» покупателю ничего не говорят, а разница
 * между 1-й и 3-й категорией одного и того же чая — это не разный рецепт,
 * а результат второго этапа производства (精制). Блок собирается по имени товара,
 * поэтому новые позиции с теми же словами получают пояснение сами.
 */
function waystea_card_terms() {

    $product = wc_get_product(get_the_ID());
    if (!$product) return;

    $name  = $product->get_name();
    $items = array();

    $slugs  = wp_get_post_terms(get_the_ID(), 'product_cat', array('fields' => 'slugs'));
    $is_red = !is_wp_error($slugs) && in_array('krasnyj-chaj', $slugs, true);

    if (mb_stripos($name, 'Цзинь Хао') !== false) {
        $items['Цзинь Хао'] = 'Цзинь Хао (金毫) — «золотой ворс». Так называют красный чай, '
            .'скрученный из молодых почек: на готовых чаинках остаётся густой золотистый пушок. '
            .'Чем его больше, тем моложе было сырьё. Даёт медово-цветочный аромат и плотный, '
            .'яркий настой.';
    }

    if (mb_stripos($name, 'Мао Фэн') !== false) {
        $items['Мао Фэн'] = 'Мао Фэн (毛峰) — «ворсистые пики». Это не сорт куста, а стандарт сбора '
            .'и вида листа: почка с одним-двумя ещё не раскрывшимися листьями, покрытыми светлым ворсом. '
            .'Отсюда название — сухой лист напоминает мохнатые горные вершины. Название встречается '
            .'и у зелёных, и у красных чаёв: сырьё разное, общий признак — молодой ворсистый лист.'
            .($is_red
                ? ' У красного чая скрутка Мао Фэн более округлая, чем у Цзинь Хао, а вкус мягче '
                  .'и более обволакивающий. При одном и том же сырье это разные стили обработки, '
                  .'а не «лучше» и «хуже».'
                : '');
    }

    // «1 категория», «первая категория», «первый сорт» — ступени сортировки.
    $graded = preg_match('/\d\s*[-—]?\s*категори/ui', $name)
        || preg_match('/(перв|втор|трет|четвёрт|четверт)\w*\s+(категори|сорт)/ui', $name)
        || mb_stripos($name, 'категория особый') !== false;

    if ($graded) {
        $items['Категория (сорт)'] = 'Категория — это не разный чай и не разный рецепт, а ступень '
            .'сортировки. Производство идёт в два этапа. Сначала первичная обработка (初制): сбор, '
            .'завяливание, скручивание, ферментация, сушка — получается черновой чай, маоча. Затем '
            .'доработка (精制): маоча просеивают, калибруют по размеру частиц, отвеивают лёгкие примеси, '
            .'выбирают огрубевшие листья, слегка прожаривают и усредняют партию. Именно на этом этапе '
            .'один и тот же чай расходится по категориям.';

        $items['Чем категории отличаются'] = 'Тремя вещами сразу. Сырьё: чем выше категория, тем моложе '
            .'и однороднее исходный лист — от почки с одним листом до почки с четырьмя-пятью. Доля '
            .'ручного труда: высшие категории дорабатывают вручную, низшие — машиной. Результат '
            .'сортировки: в высшие уходят самые ровные по калибру частицы с максимумом золотистых '
            .'кончиков, более крупные и неровные фракции опускаются ниже. Ступеней в китайской шкале '
            .'больше привычных трёх: выше первой идут «особый» и «высший», ниже третьей — четвёртая '
            .'и пятая. Низкая категория не значит испорченный чай — он просто крупнее, проще '
            .'по структуре и дешевле.';
    }

    if (!$items) return;

    $cat_link = '';
    if ($is_red) {
        $term = get_term_by('slug', 'krasnyj-chaj', 'product_cat');
        if ($term && !is_wp_error($term)) {
            $cat_link = '<p class="waystea-terms-more">'
                .($graded ? 'Национальный стандарт на гунфу хунча — GB/T 13738.2-2017. ' : '')
                .'Другие красные чаи — в разделе '
                .'<a href="'.esc_url(get_term_link($term)).'">Красный чай</a>.</p>';
        }
    }

    echo '<section class="waystea-terms"><h2>Что означает название</h2><dl>';
    foreach ($items as $t => $d) {
        echo '<dt>'.esc_html($t).'</dt><dd>'.esc_html($d).'</dd>';
    }
    echo '</dl>'.$cat_link.'</section>';
}

function waystea_card_description() {

    $product = wc_get_product(get_the_ID());
    if (!$product) return;

    $desc = $product->get_description();
    if (!$desc || mb_strlen(trim(wp_strip_all_tags($desc))) < 40) return;

    echo '<section class="waystea-desc"><h2>Описание</h2><div class="waystea-desc-body">'
        .wp_kses_post(wpautop(do_shortcode($desc)))
        .'</div></section>';
}

function waystea_card_similar() {

    $id = get_the_ID();
    // Товар обычно состоит и в профильной категории, и в каталоге-свалке
    // «Основной каталог» (333 позиции). Из свалки подбор бессмысленный —
    // к красному чаю подтягивались пиалы и доски. Берём самую узкую категорию.
    $CATCH_ALL = 15;
    $terms = wp_get_post_terms($id, 'product_cat');
    if (is_wp_error($terms) || !$terms) return;

    $terms = array_filter($terms, function ($t) use ($CATCH_ALL) {
        return (int)$t->term_id !== $CATCH_ALL && $t->count > 1;
    });
    if (!$terms) return;

    usort($terms, function ($a, $b) { return $a->count <=> $b->count; });
    $cats = array((int)$terms[0]->term_id);

    $q = new WP_Query(array(
        'post_type'           => 'product',
        'post_status'         => 'publish',
        'posts_per_page'      => 4,
        'post__not_in'        => array($id),
        'orderby'             => 'rand',
        'ignore_sticky_posts' => 1,
        'no_found_rows'       => true,
        'tax_query'           => array(
            array('taxonomy' => 'product_cat', 'field' => 'term_id', 'terms' => $cats),
            array('taxonomy' => 'product_visibility', 'field' => 'name',
                  'terms' => 'exclude-from-catalog', 'operator' => 'NOT IN'),
        ),
        'meta_query'          => array(
            array('key' => '_stock_status', 'value' => 'instock'),
        ),
    ));
    if (!$q->have_posts()) { wp_reset_postdata(); return; }

    echo '<section class="waystea-similar"><h2>Похожие чаи</h2><div class="waystea-similar-grid">';
    while ($q->have_posts()) {
        $q->the_post();
        $p = wc_get_product(get_the_ID());
        if (!$p) continue;
        $img = $p->get_image('woocommerce_thumbnail', array('loading' => 'lazy'));
        printf(
            '<a class="waystea-similar-item" href="%s">%s<span class="waystea-similar-name">%s</span>'
            .'<span class="waystea-similar-price">%s</span></a>',
            esc_url(get_permalink()),
            $img,
            esc_html($p->get_name()),
            wp_kses_post($p->get_price_html())
        );
    }
    echo '</div></section>';
    wp_reset_postdata();
}

function waystea_card_articles() {

    if (!function_exists('is_product') || !is_product()) return;

    $map = waystea_article_map();

    $slugs = wp_get_post_terms(get_the_ID(), 'product_cat', array('fields' => 'slugs'));
    if (is_wp_error($slugs) || !$slugs) return;

    $picked = array();
    foreach ($slugs as $s) {
        if (isset($map[$s])) { $picked = $map[$s]; break; }
    }
    // Ничего профильного не нашлось — даём общий вход в тему.
    if (!$picked) $picked = waystea_article_fallback();

    $links = waystea_article_links($picked);
    if (!$links) return;

    echo '<section class="waystea-read-more"><h2>'
        .esc_html(waystea_read_more_title($slugs)).'</h2><ul>'
        .implode('', $links).'</ul></section>';
}

