/** Заголовок блока: у посуды «чай» в подписи звучит нелепо. */
function waystea_read_more_title($slugs) {
    $slugs = (array) $slugs;
    if (in_array('posuda', $slugs, true)) return 'Разобраться в чайной посуде';
    return 'Разобраться в этом чае';
}

/** Список <li> со ссылками на существующие опубликованные статьи. */
function waystea_article_links($picked) {
    $links = array();
    foreach ($picked as $p) {
        $post = get_page_by_path($p[0], OBJECT, 'post');
        if ($post && $post->post_status === 'publish') {
            $links[] = '<li><a href="'.esc_url(get_permalink($post)).'">'.esc_html($p[1]).'</a></li>';
        }
    }
    return $links;
}

/**
 * Страница категории: блок «Разобраться в чае» + соседние категории.
 *
 * Раньше с категории вёл только путь в карточку товара: человек приходил
 * из поиска, не покупал и уходил. Хук проверен на живой странице —
 * woocommerce_archive_description под этой темой не вызывается,
 * woocommerce_after_shop_loop вызывается дважды, поэтому стоит защёлка.
 */
add_action('woocommerce_after_shop_loop', function () {
    static $done = false;
    if ($done) return;
    if (!function_exists('is_product_category') || !is_product_category()) return;
    $done = true;

    $term = get_queried_object();
    if (!$term || empty($term->slug)) return;

    $map    = waystea_article_map();
    $picked = isset($map[$term->slug]) ? $map[$term->slug] : waystea_article_fallback();
    $links  = waystea_article_links($picked);

    // Соседние категории — второй путь вглубь сайта.
    $siblings = array();
    $terms = get_terms(array(
        'taxonomy'   => 'product_cat',
        'hide_empty' => true,
        'exclude'    => array((int) $term->term_id, 15),
        'orderby'    => 'count',
        'order'      => 'DESC',
        'number'     => 6,
    ));
    if (!is_wp_error($terms)) {
        foreach ($terms as $t) {
            $siblings[] = '<a href="'.esc_url(get_term_link($t)).'">'.esc_html($t->name).'</a>';
        }
    }

    if (!$links && !$siblings) return;

    echo '<section class="waystea-cat-more">';
    if ($links) {
        echo '<h2>'.esc_html(waystea_read_more_title($term->slug)).'</h2><ul>'
            .implode('', $links).'</ul>';
    }
    if ($siblings) {
        echo '<div class="waystea-cat-sib"><span>Другие виды чая:</span> '
            .implode(' <i>·</i> ', $siblings).'</div>';
    }
    echo '</section>';
}, 20);

